_stocked = {}
_reserved = {}

def available(sku):
    return max(0, _stocked.get(sku, 0) - _reserved.get(sku, 0))

def reserve(sku, n):
    if n > available(sku):
        raise ValueError("insufficient stock")
    _reserved[sku] = _reserved.get(sku, 0) + n
    return available(sku)

def release(sku, n):
    _reserved[sku] = max(0, _reserved.get(sku, 0) - n)
    return available(sku)

def receive(sku, n):
    _stocked[sku] = _stocked.get(sku, 0) + n
    return _stocked[sku]

def value(catalog):
    return sum(_stocked.get(sku, 0) * price for sku, price in catalog.items())

def low_stock(threshold):
    skus = set(_stocked) | set(_reserved)
    return sorted(sku for sku in skus if available(sku) <= threshold)

